import json, glob, collections, sys, re

BASE = '/private/tmp/claude-501/-Users-kevingalligan-devel-framejob/9cfd7405-83ec-4caa-905f-7b97a20f2cc9/scratchpad/inventory/'


def load():
    recs = []
    for f in sorted(glob.glob(BASE + 'raw/*.json')):
        recs += json.load(open(f))
    return recs


def fmt(r):
    s = f"{r['id']} | {r.get('name')} [{r.get('area')}]\n  W: {r.get('what')}\n"
    if r.get('ui'):
        s += f"  UI: {r['ui']}\n"
    if r.get('mcp'):
        s += f"  MCP: {r['mcp']}\n"
    if r.get('requires'):
        s += f"  REQ: {r['requires']}\n"
    if r.get('shortcuts'):
        s += f"  KEY: {r['shortcuts']}\n"
    if r.get('details'):
        s += "  D: " + " ;; ".join(map(str, r['details'])) + "\n"
    s += f"  E: {r.get('evidence')}\n"
    return s


if __name__ == '__main__':
    recs = load()
    print(collections.Counter(k for r in recs for k in r))
    mine = [r for r in recs if r.get('area') in ('projects', 'media')]
    print(len(mine))
    print(collections.Counter(r['id'].rsplit('-', 1)[0] for r in mine))
    open(BASE + 'merge-projects/mine.txt', 'w').write("\n".join(fmt(r) for r in mine))

